import{_ as i,C as e,o as n,c as d,E as a,a2 as l}from"./chunks/framework.Cc8dJFaW.js";const k=JSON.parse('{"title":"请求经过了策略，干预就生效了吗？","description":"","frontmatter":{"title":"请求经过了策略，干预就生效了吗？","article_type":"comparative-study","edition":"research-center","research_question":"策略覆盖一条执行路径，与忠实执行该路径上声明的干预，是哪些不同的证据义务？","summary":"比较代理路由与动作钩子的证据边界，用固定源码的局部方法探针说明：路径覆盖清单和干预输入输出必须分别验收。","sources":["https://architect.salesforce.com/docs/architect/fundamentals/guide/mulesoft-architecting-agentic-enterprise","https://arxiv.org/html/2503.18666v3","https://github.com/haoyuwang99/AgentSpec/tree/e6fa3902e2cfb9681f454b355691b771f70543f8"],"date":"2026-11-25","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261125-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-25-sig-20261125-002-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-25-sig-20261125-002.md","filePath":"zh/industry/2026-11-25-sig-20261125-002.md","lastUpdated":1795608779000}'),o={name:"zh/industry/2026-11-25-sig-20261125-002.md"};function h(c,t,p,f,g,b){const r=e("ArticleCover"),s=e("ArticleTableScroll");return n(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-11-25-sig-20261125-002-cover.png",kicker:"研究成果",title:"请求经过了策略，干预就生效了吗？",summary:"比较代理路由与动作钩子的证据边界，用固定源码的局部方法探针说明：路径覆盖清单和干预输入输出必须分别验收。",version:"2026-11-25",languageHref:"/en/industry/2026-11-25-sig-20261125-002",languageLabel:"English"}),a(s,{language:"zh"}),t[0]||(t[0]=l(`<h1 id="请求经过了策略-干预就生效了吗" tabindex="-1">请求经过了策略，干预就生效了吗？ <a class="header-anchor" href="#请求经过了策略-干预就生效了吗" aria-label="Permalink to &quot;请求经过了策略，干预就生效了吗？&quot;">​</a></h1><p>一次工具请求确实经过检查点，能说明什么？至少还不能据此认定，声明在该处的每项干预都按预期执行。对集成智能体策略的平台与安全工程师，本文提出两份应分开验收的记录：哪些路径经过策略，以及策略究竟把动作改成了什么。</p><p>下面比较代理网关的路由设计与进程内的动作钩子，再查看一组局部源码方法探针。关键差别是：前者回答“看见了哪些交互”，后者还需回答“保留并执行了什么干预”。两者可以互补，不能互相代证。</p><h2 id="路由边界与动作边界看见的对象不同" tabindex="-1">路由边界与动作边界看见的对象不同 <a class="header-anchor" href="#路由边界与动作边界看见的对象不同" aria-label="Permalink to &quot;路由边界与动作边界看见的对象不同&quot;">​</a></h2><p>Salesforce（赛富时）的架构指南描述了 MuleSoft（企业集成平台）网关针对工具、资源与调用者属性设置策略的设计。其中，MCP（模型上下文协议）属性访问控制针对协议服务暴露的工具与资源；A2A（智能体间通信协议）代理卡片策略则重写地址，以使流量经过受治理的代理。<a href="https://architect.salesforce.com/docs/architect/fundamentals/guide/mulesoft-architecting-agentic-enterprise" target="_blank" rel="noreferrer">该指南</a>把路由本身纳入治理机制。</p><p>这是供应方对架构的陈述，不是本文对已部署网络覆盖率的测量。特别是，文档中的代理路径不能自行承担任意本地动作的覆盖证明。</p><p>另一种边界位于智能体内部。AgentSpec（智能体规则约束框架）论文在执行动作前、获得观察后及任务结束时设置干预点；已检查的真实执行器源码在执行工具动作之前调用校验与干预方法。前者是论文所述机制，后者是固定版本的静态观察，不能合并成全路径执行结果。<a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">论文第 4 节</a>；<a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/controlled_agent_excector.py" target="_blank" rel="noreferrer">固定版本执行器</a>（保留仓库原文件名）。</p><table tabindex="0"><thead><tr><th>比较维度</th><th>代理网关样本</th><th>动作钩子样本</th></tr></thead><tbody><tr><td>被观察对象</td><td>经代理的协议交互</td><td>已插桩的动作、观察与结束事件</td></tr><tr><td>首先需要举证</td><td>相关流量确实走过配置的代理</td><td>相关动作确实走过已检查的钩子</td></tr><tr><td>仍需另行举证</td><td>策略在目标配置下的实际效果</td><td>声明的干预如何成为实际动作</td></tr></tbody></table><p>表中是根据上述两个来源形成的研究比较，不是产品能力排名。比如，一个智能体通过远程工具写文件，也能在本地启动进程：这是解释检查范围的示意场景，并非本轮观察到的旁路。验收人员应分别查明两条路径由谁拦截，而不能凭其中一条的日志宣称覆盖完整。</p><h2 id="两次回调进入之后-留下的是一个值" tabindex="-1">两次回调进入之后，留下的是一个值 <a class="header-anchor" href="#两次回调进入之后-留下的是一个值" aria-label="Permalink to &quot;两次回调进入之后，留下的是一个值&quot;">​</a></h2><p>同日 Analysis（研究分析阶段）已运行一组内部局部探针。它提取固定提交 <code>e6fa3902e2cfb9681f454b355691b771f70543f8</code>（本次受测源码的版本指纹）的原始方法，去除第三方类型注解而保持方法体不变，用合成上下文直接调用。环境为 Windows（微软桌面操作系统）上的 Python（编程语言）3.12.9；未调用模型或网络。本文复用其已验证结果，没有在写作阶段增加实验。</p><p>解释器的进入干预回调方法 <code>enterEnforcement</code>（进入干预子句的回调）读取上下文文本，并写入一个成员值。下面是<a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/interpreter.py#L105-L109" target="_blank" rel="noreferrer">固定版本源码</a>的方法体节选：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.check:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.enforce </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctx.getText()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.enforce </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;none&quot;</span></span></code></pre></div><p>内部探针的结果如下。表内“跳过”“停止”“无干预”分别对应源码字符串 <code>skip</code>（跳过当前动作）、<code>stop</code>（停止）和 <code>none</code>（无干预）；这里报告的是保留字符串，没有执行这些字符串指向的工具效果。</p><table tabindex="0"><thead><tr><th>检查条件</th><th>人为给定的回调顺序</th><th>每次调用后的值</th><th>最后保留值</th></tr></thead><tbody><tr><td>真</td><td>跳过</td><td>跳过</td><td>跳过</td></tr><tr><td>真</td><td>跳过 → 停止</td><td>跳过 → 停止</td><td>停止</td></tr><tr><td>真</td><td>停止 → 跳过</td><td>停止 → 跳过</td><td>跳过</td></tr><tr><td>假</td><td>跳过 → 停止</td><td>无干预 → 无干预</td><td>无干预</td></tr></tbody></table><p>来源为<a href="/joinwell52/assets/evidence/2026-11-25-sig-20261125-002/method-probe.json">内部方法探针记录</a>。这组对照支持一个很窄的观察：受测回调把后来文本赋给同一存储位置，倒序会改变最终保留值。它足以反驳“多次进入该方法就必然累积保存全部干预”的假设。</p><p>它还不足以说明真实规则经过解析后会产生同样的回调序列。语法允许多个干预子句，但本次没有运行原始规则解析、规则集成或完整执行器；合成上下文的顺序由探针指定。把这个结果写成“系统丢弃多条规则”会越过证据：子句和规则不是同一层级，局部方法与端到端行为也不是同一验证对象。</p><h2 id="返回动作-也不等于调用了替代工具" tabindex="-1">返回动作，也不等于调用了替代工具 <a class="header-anchor" href="#返回动作-也不等于调用了替代工具" aria-label="Permalink to &quot;返回动作，也不等于调用了替代工具&quot;">​</a></h2><p>同一内部探针还检查了两个调用辅助方法。<code>InvokeAction.apply</code>（调用动作类的应用方法）返回继续执行标记和传入的原动作对象，保持对象身份不变。另一个解释器辅助方法面对两份不同的合成请求，都返回相同的固定交通灯字典。已检查的映射表也没有把调用动作名称接到这个类上。<a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/enforcement.py" target="_blank" rel="noreferrer">干预实现</a>；<a href="/joinwell52/assets/evidence/2026-11-25-sig-20261125-002/method-probe.json">内部记录</a>。</p><p>这不构成“替代工具已被调用”的证据。类名、返回字典和可达调用链是三个不同对象；若读者要验收替代动作，仍需看到规则经过真实解析、进入目标实现，最后由实际工具产生预期效果的完整对应关系。</p><p>这也不是一个已证实的部署漏洞。辅助方法可能是未完成路径，实际使用者可能只依赖其他干预方式。本文没有安装完整依赖、运行真实工具，也没有将虚拟执行器的行为移植为真实执行器的结论。</p><h2 id="把验收写成两份可核对记录" tabindex="-1">把验收写成两份可核对记录 <a class="header-anchor" href="#把验收写成两份可核对记录" aria-label="Permalink to &quot;把验收写成两份可核对记录&quot;">​</a></h2><p>根据这些证据，我们建议将路径覆盖清单与干预语义对照分开保存。这是测试设计建议，不是两个样本已经实现的统一验收功能。</p><table tabindex="0"><thead><tr><th>记录</th><th>至少登记什么</th><th>本轮证据达到哪里</th></tr></thead><tbody><tr><td>路径覆盖</td><td>产生效果的入口、实际路由或钩子、配置版本、经过与未经过的对照</td><td>仅有文档设计与固定源码观察；没有部署清单</td></tr><tr><td>干预语义</td><td>固定实现版本、原动作、声明顺序、预期组合规则、实际返回动作和工具效果</td><td>仅有局部回调与辅助方法结果；没有真实解析或效果记录</td></tr></tbody></table><p>具体实施时，可把一项写文件请求作为贯穿夹具。先列出协议工具调用与本地进程入口，记录各自经过的策略边界；再为已经进入边界的那条路径，分别执行单个干预、交换子句顺序、条件为假三类对照。若声明了替代动作，额外核对实际工具收到的参数与效果。这个例子是建议的验证流程，本轮没有执行。</p><p>在这套建议中，平台维护者将入口与配置交给覆盖检查，策略作者给出组合合同和期望结果，集成人员提交解析、动作与效果记录，验收人员核对两份证据是否指向同一请求。入口遗漏、合同不明或效果不可核对时，应暂停该项验收，返回缺失证据，而不是认定系统已通过。</p><p>不要先默认多个干预必须累积。先确定合同规定的是顺序组合、优先级还是最后值优先，再定义期望值。只有期望规则明确，观察到差异才有资格进入缺陷判定。若解析或运行失败，也应保存失败与已到达的位置，不能把“没有效果”默认为策略成功阻止了动作。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>这里的来源陈述只说明作者描述了什么；源码观察只说明固定文件中出现了什么；内部实验依据只说明合成输入下的受测方法结果。它们均不等于独立复现或安全认证。</p><ul><li><a href="https://architect.salesforce.com/docs/architect/fundamentals/guide/mulesoft-architecting-agentic-enterprise" target="_blank" rel="noreferrer">企业智能体架构指南</a>：Salesforce 架构团队的官方设计文档，承担代理策略与路由主张；同日读取快照未明确提供更新日期。</li><li><a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">智能体规则约束框架论文，第 3 版</a>：AgentSpec 作者团队，2025 年 7 月 31 日版本，承担动作钩子机制及局限；这是既有研究比较，不是今日发布新闻。论文中的基准结果不作为本文的新测量，也不能替代本地集成验收。</li><li><a href="https://github.com/haoyuwang99/AgentSpec/tree/e6fa3902e2cfb9681f454b355691b771f70543f8" target="_blank" rel="noreferrer">固定提交源码</a>：同一研究团队的实现材料，与论文归为一个作者主体。</li><li><a href="/joinwell52/assets/evidence/2026-11-25-sig-20261125-002/method-probe.json">方法探针记录</a>：同日内部实验的范围、方法节选、输入、实际结果与限制；只复用已执行证据，没有重新运行完整框架。</li></ul><p>Salesforce 与 AgentSpec 是两个独立作者主体，各自支持比较的一侧，并未相互验证。论文、源码及其托管地址不能拆成多个独立来源。发表、引用和评审状态不能推出理论有效；一次实现成功也不能推出普遍成立。</p><h2 id="仍需解析器与真实效果回答的问题" tabindex="-1">仍需解析器与真实效果回答的问题 <a class="header-anchor" href="#仍需解析器与真实效果回答的问题" aria-label="Permalink to &quot;仍需解析器与真实效果回答的问题&quot;">​</a></h2><p>一个合理的替代解释是：最后值优先本来就是维护者希望的组合语义。另一个是：真实解析器不会向同一个监听器产生探针给定的多回调序列。两者都需要规范和集成证据，不能靠局部赋值语句排除。</p><p>因此，本文的方法对单个标量回调的行为判断适用，对长期动作序列安全、所有入口无旁路或生产部署可靠性均不适用。论文也明确将离散干预与长期轨迹安全分析区分开。</p><p>下一步最有判别力的验证，是在固定版本上让真实规则穿过解析器，逐项记录组合合同、回调序列、最终动作与实际工具效果；另建部署入口清单检查路由。只有两条证据链都落到同一条目标执行路径上，才能回答那次请求的策略究竟完成了什么。</p>`,35))])}const m=i(o,[["render",h]]);export{k as __pageData,m as default};
